import pyomo.environ as pyo

DATA = {
    "cities": [0, 1, 2, 3, 4, 5],
    "depot": 0,
    "cost": {
        (0, 1): 321, (0, 2): 294, (0, 3): 323, (0, 4): 286, (0, 5): 325,
        (1, 0): 290, (1, 2): 319, (1, 3): 321, (1, 4): 280, (1, 5): 324,
        (2, 0): 304, (2, 1): 317, (2, 3): 322, (2, 4): 313, (2, 5): 300,
        (3, 0): 312, (3, 1): 324, (3, 2): 280, (3, 4): 318, (3, 5): 284,
        (4, 0): 289, (4, 1): 279, (4, 2): 278, (4, 3): 301, (4, 5): 324,
        (5, 0): 325, (5, 1): 309, (5, 2): 304, (5, 3): 305, (5, 4): 310,
    },
    "position_lb": 0,
    "position_ub": 5,
    "big_m": 6,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    cities = d["cities"]
    depot = d["depot"]
    cost = d["cost"]
    arcs = [(i, j) for i in cities for j in cities if i != j]

    model = pyo.ConcreteModel()

    model.C = pyo.Set(initialize=cities)
    model.A = pyo.Set(initialize=arcs, dimen=2)

    # route[i,j] = 1 if the tour goes directly from city i to city j
    model.route = pyo.Var(model.A, domain=pyo.Binary)

    # position[i] = order in which city i is visited
    def pos_bounds(m, i):
        if i == depot:
            return (0, 0)
        return (d["position_lb"], d["position_ub"])

    model.position = pyo.Var(
        model.C, domain=pyo.Reals, bounds=pos_bounds
    )

    # Objective: minimize total travel cost
    def obj_rule(m):
        return sum(cost[(i, j)] * m.route[i, j] for (i, j) in m.A)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Each city departed exactly once
    def depart_rule(m, i):
        return sum(m.route[i, j] for j in m.C if (i, j) in m.A) == 1

    model.depart_once = pyo.Constraint(model.C, rule=depart_rule)

    # Each city entered exactly once
    def arrive_rule(m, j):
        return sum(m.route[i, j] for i in m.C if (i, j) in m.A) == 1

    model.arrive_once = pyo.Constraint(model.C, rule=arrive_rule)

    # MTZ subtour elimination: position[j] >= position[i] + 1 - N*(1 - route[i,j])
    def mtz_rule(m, i, j):
        return (
            m.position[j]
            >= m.position[i] + 1 - d["big_m"] * (1 - m.route[i, j])
        )

    model.subtour = pyo.Constraint(model.A, rule=mtz_rule)

    return model
